-- The Inner voice is now one roomy Reverb. A library still on the first chain moves over; one
-- whose Inner voice was edited keeps its own.
UPDATE `effects` SET `chain` = '[{"plugin":"Reverb","params":{"room_size":0.55,"damping":0.48,"wet_level":0.62,"dry_level":0.74,"width":0.85},"on":true}]' WHERE `id` = 'inner-voice' AND `chain` = '[{"plugin":"HighpassFilter","params":{"cutoff_frequency_hz":220},"on":true},{"plugin":"LowpassFilter","params":{"cutoff_frequency_hz":6000},"on":true},{"plugin":"PeakFilter","params":{"cutoff_frequency_hz":2500,"gain_db":-4,"q":1},"on":true},{"plugin":"Compressor","params":{"threshold_db":-20,"ratio":3},"on":true},{"plugin":"Reverb","params":{"room_size":0.12,"damping":0.5,"wet_level":0.18,"dry_level":0.9},"on":true},{"plugin":"Gain","params":{"gain_db":-1},"on":true}]';
